func TestPythonCredentialsRemainValid(t *testing.T) {
	// Generated by Python 1.3.1 with a public test secret/password only.
	token := "eyJ2IjoxLCJhdXRoZW50aWNhdGVkIjp0cnVlfQ.aszLwA.4zFI0HMRfNvC89ZE7qKnHK0N5ac2i7auzbZ8cEpDYGk"
	now := time.Unix(1791806401, 0)
	if !ValidSession("test-only-session-secret", token, now) {
		t.Fatal("legacy token rejected")
	}
	if ValidSession("wrong", token, now) || ValidSession("test-only-session-secret", token, now.Add(8*24*time.Hour)) {
		t.Fatal("invalid token accepted")
	}
	hash := "$argon2id$v=19$m=65536,t=3,p=4$BOdOZcYBeiLNqhGg5CZJXg$cgkG9Eb78Io3gbX3IeoqgTq6MQNKdYpS7EPjzmw987Q"
	ok, err := VerifyPassword(hash, "123456")
	if err != nil || !ok {
		t.Fatalf("legacy password rejected: %v", err)
	}
	ok, err = VerifyPassword(hash, "654321")
	if err != nil || ok {
		t.Fatalf("wrong password accepted: %v", err)
	}
}

func TestSessionPayloadMustBeSingleObject(t *testing.T) {
	now := time.Unix(1791806401, 0)
	secret := "test-only-session-secret"
	parts := strings.Split(CreateSession(secret, now), ".")
	for _, raw := range []string{`{"v":1,"authenticated":true} {}`, `{"v":1,"authenticated":true} garbage`} {
		value := base64.RawURLEncoding.EncodeToString([]byte(raw)) + "." + parts[1]
		if ValidSession(secret, value+"."+sessionSign(secret, value), now) {
			t.Fatalf("accepted trailing signed payload: %s", raw)
		}
	}
	var b bytes.Buffer
	z := zlib.NewWriter(&b)
	_, _ = z.Write([]byte(`{"v":1,"authenticated":true}`))
	if err := z.Close(); err != nil {
		t.Fatal(err)
	}
	value := "." + base64.RawURLEncoding.EncodeToString(b.Bytes()) + "." + parts[1]
	compressed := value + "." + sessionSign(secret, value)
	if !ValidSession(secret, compressed, now) {
		t.Fatal("legacy compressed session rejected")
	}
	if ValidSession(secret, compressed, now.Add(-time.Second)) {
		t.Fatal("future session accepted")
	}
}

func TestPasswordHashRejectsMalformedParameters(t *testing.T) {
	hash := "$argon2id$v=19$m=65536,t=3,p=4$BOdOZcYBeiLNqhGg5CZJXg$cgkG9Eb78Io3gbX3IeoqgTq6MQNKdYpS7EPjzmw987Q"
	for _, malformed := range []string{
		"prefix" + hash,
		strings.Replace(hash, "m=65536,t=3,p=4", "m=65536,t=3,p=4,x=1", 1),
		strings.Replace(hash, "m=65536,t=3,p=4", "m=1,m=65536,t=3,p=4", 1),
	} {
		if ok, err := VerifyPassword(malformed, "123456"); ok || err == nil {
			t.Fatalf("malformed hash accepted: %v %v", ok, err)
		}
	}
}

func TestLoginLimiterReleasesInflightAndExpiresFailures(t *testing.T) {
	l := &loginAttempts{failures: map[string][]time.Time{}, inflight: map[string]int{}}
	now := time.Unix(1791806401, 0)
	for i := 0; i < 5; i++ {
		if !l.start("host", now) {
			t.Fatal("too early rejection")
		}
	}
	if l.start("host", now) {
		t.Fatal("did not count in-flight attempts")
	}
	for i := 0; i < 5; i++ {
		l.finish("host", now, false, true)
	}
	if _, ok := l.inflight["host"]; ok {
		t.Fatal("completed in-flight counter retained")
	}
	if l.start("host", now.Add(5*time.Minute-time.Nanosecond)) {
		t.Fatal("failure limit released early")
	}
	if !l.start("host", now.Add(5*time.Minute)) {
		t.Fatal("failure limit did not expire")
	}
	l.finish("host", now.Add(5*time.Minute), false, false)
	if len(l.failures) != 0 || len(l.inflight) != 0 {
		t.Fatal("expired/canceled attempt retained")
	}
}

func TestAuthCorruptHashDoesNotConsumeAttemptsAndPeerIsolation(t *testing.T) {
	h := dlNewHarness(t)
	RegisterAuth(h.s)
	if _, err := h.db.Exec("INSERT INTO auth_secret VALUES(1,'corrupt','2026-10-12')"); err != nil {
		t.Fatal(err)
	}
	login := func(peer, password string) *httptest.ResponseRecorder {
		t.Helper()
		r := httptest.NewRequest("POST", "/api/auth/login", strings.NewReader(`{"password":"`+password+`"}`))
		r.RemoteAddr = peer
		r.Header.Set("X-Forwarded-For", "192.0.2.2")
		w := httptest.NewRecorder()
		h.s.ServeHTTP(w, r)
		return w
	}
	for i := 0; i < 6; i++ {
		if w := login("192.0.2.1:1234", "123456"); w.Code != 500 {
			t.Fatalf("corrupt hash should remain server error: %d %s", w.Code, w.Body.String())
		}
	}
	hash := "$argon2id$v=19$m=65536,t=3,p=4$BOdOZcYBeiLNqhGg5CZJXg$cgkG9Eb78Io3gbX3IeoqgTq6MQNKdYpS7EPjzmw987Q"
	if _, err := h.db.Exec("UPDATE auth_secret SET password_hash=?", hash); err != nil {
		t.Fatal(err)
	}
	w := login("192.0.2.1:1234", "123456")
	if w.Code != 204 || !strings.Contains(w.Header().Get("Set-Cookie"), "SameSite=lax") {
		t.Fatalf("hash repair/login failed: %d %v", w.Code, w.Header())
	}
	for i := 0; i < 5; i++ {
		if w := login("192.0.2.1:1234", "654321"); w.Code != 401 {
			t.Fatalf("wrong password status %d", w.Code)
		}
	}
	if w := login("192.0.2.1:1234", "123456"); w.Code != 429 {
		t.Fatalf("limited peer status %d", w.Code)
	}
	if w := login("192.0.2.2:1234", "654321"); w.Code != 401 {
		t.Fatalf("forwarded header changed peer isolation: %d", w.Code)
	}
}
